import {state} from '../services/store.js?v=65';
import {esc,safeURL,progress} from '../utils/helpers.js?v=65';
import {dateLabel,today} from '../utils/dates.js?v=65';
import {field,options,openModal,bindForm,confirmDelete} from '../utils/dom.js?v=65';
import {saveProject,remove} from '../services/dataService.js?v=65';
import {taskTable} from './tasks.js?v=65';
import {attachmentsSection} from './attachments.js?v=65';
import {universityData,encodeUniversity,validateSubject,universityStats,studyStatuses} from '../utils/university.js?v=65';
let query='',status='',archived=false;
const num=n=>n===null?'—':new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(n);
const grade=d=>d.passFail?'Idoneità':d.grade===null||d.grade===undefined?'—':`${d.grade}${d.honours?' e lode':''}/30`;
const showDate=value=>value?dateLabel(value,state.timezone):'Da definire';
function metrics(list){const s=universityStats(list);return `<div class="university-metrics">${[['Esami superati',`${s.passed} / ${s.subjects}`],['CFU acquisiti',`${num(s.credits)} / ${num(s.totalCredits)}`],['Media ponderata',s.weighted===null?'—':`${num(s.weighted)} / 30`],['Media aritmetica',s.mean===null?'—':`${num(s.mean)} / 30`]].map(([label,value])=>`<div class="panel"><span class="subtext">${label}</span><strong>${value}</strong></div>`).join('')}</div><p class="subtext">Medie sui soli esami superati con voto. La media ponderata usa i CFU; le idoneità sono escluse e la lode vale 30. Totali riferiti alle materie inserite${s.missingCredits?` · ${s.missingCredits} esami superati senza CFU indicati`:''}.</p>`;}
export function universityPage(id){
 const all=state.projects.filter(p=>universityData(p));
 if(id){const p=all.find(p=>p.id===id);return p?subjectPage(p):'<div class="panel empty">Materia non trovata. <a href="#/university">Torna a Università</a></div>';}
 const list=all.filter(p=>(p.status==='archived')===archived).filter(p=>(!status||universityData(p).studyStatus===status)&&[p.name,...Object.values(universityData(p))].join(' ').toLocaleLowerCase('it').includes(query.toLocaleLowerCase('it')));
 const upcoming=all.filter(p=>{const d=universityData(p);return p.status!=='archived'&&d.studyStatus!=='passed'&&d.examDate&&d.examDate>=today(state.timezone);}).sort((a,b)=>universityData(a).examDate.localeCompare(universityData(b).examDate)).slice(0,5);
 return `<div class="page-heading"><div><h1>Università</h1><p class="subtext">Materie, piano di studio e libretto degli esami.</p></div><button class="btn primary" data-new-subject>＋ Aggiungi materia</button></div>${metrics(all)}${upcoming.length?`<section class="panel university-upcoming"><h2>Prossimi esami</h2>${upcoming.map(p=>{const d=universityData(p);return `<a href="#/university/${p.id}"><strong>${esc(p.name)}</strong><span>${esc(showDate(d.examDate))}${d.examTime?' · '+esc(d.examTime):''}${d.location?' · '+esc(d.location):''}</span></a>`;}).join('')}</section>`:''}<form id="university-filter" class="filters"><input name="query" aria-label="Cerca materia, docente o corso" placeholder="Cerca materia, docente o corso…" value="${esc(query)}"><select name="status" aria-label="Stato di studio">${options(studyStatuses,status,'Tutti gli stati')}</select><label class="university-archive-toggle"><input type="checkbox" name="archived" ${archived?"checked":""}> Materie archiviate</label><button class="btn" type="submit">Filtra</button><button class="btn" type="button" data-university-reset>Azzera</button></form><div class="projects-grid">${list.map(p=>{const d=universityData(p),tasks=state.tasks.filter(t=>t.project_id===p.id);return `<article class="panel university-card"><div class="panel-head"><span class="badge">${studyStatuses[d.studyStatus]||'Da iniziare'}</span><span>${d.credits?num(d.credits)+' CFU':'CFU da definire'}</span></div><h2><a href="#/university/${p.id}">${esc(p.name)}</a></h2><p class="subtext">${esc([d.degree,d.academicYear].filter(Boolean).join(' · ')||'Corso non indicato')}</p><p>${d.studyStatus==='passed'?`Voto: <strong>${esc(grade(d))}</strong>`:`Esame: ${esc(showDate(d.examDate))}`}</p><label class="subtext">Studio: ${tasks.filter(t=>t.status==='completed').length} / ${tasks.length} attività completate<progress max="100" value="${progress(tasks)}"></progress></label><div class="heading-actions"><a class="btn" href="#/university/${p.id}">Apri materia</a><button class="btn" data-edit-subject="${p.id}">Modifica</button></div></article>`;}).join('')||'<div class="panel empty"><h2>Nessuna materia da mostrare</h2><p>Aggiungi la prima materia oppure modifica i filtri.</p></div>'}</div>${all.some(p=>p.status==='archived')?'<p class="subtext">Le materie archiviate restano nel libretto. Spunta “Materie archiviate” per consultarle.</p>':''}`;
}
function subjectPage(p){const d=universityData(p),tasks=state.tasks.filter(t=>t.project_id===p.id);const details=[['Ateneo',d.institution],['Corso di laurea',d.degree],['Anno accademico',d.academicYear],['Anno di corso',d.year],['Semestre',d.semester],['Codice insegnamento',d.code],['Docente',d.professor],['Email docente',d.email],['CFU',d.credits],['Stato',studyStatuses[d.studyStatus]],['Voto',d.studyStatus==='passed'?grade(d):'—'],['Data esame',showDate(d.examDate)],['Ora',d.examTime],['Iscrizione entro',d.enrolmentDate?showDate(d.enrolmentDate):''],['Modalità esame',d.examMode],['Aula / sede',d.location],['Lezioni e ricevimento',d.schedule]];
 return `<a class="link" href="#/university">← Università</a><div class="page-heading"><div><h1>${esc(p.name)}</h1><p class="subtext">${esc(p.description||'')}</p></div><button class="btn" data-edit-subject="${p.id}">Modifica materia / voto</button></div><section class="panel university-details"><dl>${details.filter(([,v])=>v!==''&&v!==null&&v!==undefined).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${safeURL(p.project_url)?`<a class="link" href="${esc(safeURL(p.project_url))}" target="_blank" rel="noopener">Pagina del corso / materiali ↗</a>`:''}</section>${[['Programma e obiettivi',d.syllabus],['Libri e materiali',d.books],['Appunti',d.notes]].filter(([,v])=>v).map(([label,text])=>`<section class="panel university-text"><h2>${label}</h2><p>${esc(text)}</p></section>`).join('')}<div class="page-heading"><div><h2>Cose da studiare</h2><p class="subtext">${tasks.filter(t=>t.status==='completed').length} di ${tasks.length} attività completate</p></div><div class="heading-actions"><button class="btn" data-action="import-checklist" data-project="${p.id}">Importa checklist</button><button class="btn primary" data-action="new-task" data-project="${p.id}">＋ Attività di studio</button></div></div>${p.status==='archived'?'<p class="subtext">Materia archiviata: riattivala da “Modifica materia / voto” per aggiungere attività.</p>':''}${taskTable(tasks)}${attachmentsSection(p.id)}`;
}
export function subjectForm(existing,onSave){
 const d=universityData(existing)||{studyStatus:'planned',credits:'',grade:''},p=existing||{color:'#0d7191'};
 openModal(existing?'Modifica materia e voto':'Aggiungi materia',`<form id="subject-form"><div class="form-grid">${field('Materia *','name',p.name,'text','required maxlength="120"')}${field('Codice insegnamento','code',d.code)}${field('Ateneo','institution',d.institution)}${field('Corso di laurea','degree',d.degree)}${field('Anno accademico','academicYear',d.academicYear,'text','placeholder="2026/2027"')}${field('Anno di corso','year',d.year,'number','min="1" max="10"')}${field('Semestre','semester',d.semester)}${field('CFU','credits',d.credits??'','number','min="0.5" max="120" step="0.5"')}<label class="field">Stato di studio<select name="studyStatus">${options(studyStatuses,d.studyStatus)}</select></label>${field('Voto (18–30)','grade',d.grade??'','number','min="18" max="30" step="1"')}<label class="field"><span>Lode</span><span><input type="checkbox" name="honours" ${d.honours?'checked':''}> 30 e lode</span></label><label class="field"><span>Esame senza voto</span><span><input type="checkbox" name="passFail" ${d.passFail?'checked':''}> Idoneità</span></label>${field('Data esame','examDate',d.examDate,'date')}${field('Ora esame','examTime',d.examTime,'time')}${field('Iscrizione entro','enrolmentDate',d.enrolmentDate,'date')}${field('Modalità esame','examMode',d.examMode,'text','placeholder="Scritto, orale, progetto…"')}${field('Docente','professor',d.professor)}${field('Email docente','email',d.email,'email')}${field('Aula / sede','location',d.location)}${field('Lezioni e ricevimento','schedule',d.schedule)}${field('Pagina del corso / materiali','project_url',p.project_url,'url')}${field('Colore','color',p.color,'color')}<label class="field full">Descrizione<textarea name="description" maxlength="2000">${esc(p.description)}</textarea></label><label class="field full">Programma e obiettivi<textarea name="syllabus" rows="4" maxlength="12000">${esc(d.syllabus)}</textarea></label><label class="field full">Libri, bibliografia e link ai materiali<textarea name="books" rows="3" maxlength="6000">${esc(d.books)}</textarea></label><label class="field full">Appunti<textarea name="notes" rows="4" maxlength="20000">${esc(d.notes)}</textarea></label></div>${existing?`<label class="bulk-delete-accept"><input type="checkbox" name="archived" ${existing.status==='archived'?'checked':''}>Materia archiviata</label>`:""}<p class="subtext">Gli esami superati con voto contribuiscono alle medie. Le idoneità contribuiscono ai CFU acquisiti.</p><div class="form-actions">${existing?'<button class="btn danger" type="button" id="delete-subject">Elimina materia</button>':''}<button class="btn primary" type="submit">Salva materia</button></div><p class="form-error" role="alert"></p></form>`);
 bindForm('subject-form',async data=>{const raw=Object.fromEntries(data),values=validateSubject({...raw,honours:data.has('honours'),passFail:data.has('passFail')});const payload={name:raw.name.trim(),description:raw.description||'',color:raw.color,notes:encodeUniversity(values),status:data.has('archived')?'archived':({planned:'planned',studying:'active',ready:'active',passed:'completed'}[values.studyStatus]),due_date:values.examDate||null,start_date:existing?.start_date||null,project_url:raw.project_url||null,github_url:existing?.github_url||null,icon:existing?.icon||null};await saveProject(payload,existing);onSave();});
 if(existing)document.querySelector('#delete-subject').onclick=()=>confirmDelete(`Eliminare “${existing.name}”, il voto e tutte le attività collegate?`,async()=>{await remove('projects',existing.id);location.hash='#/university';onSave();});
}
export function bindUniversity(render){document.querySelectorAll('[data-new-subject]').forEach(b=>b.onclick=()=>subjectForm(null,render));document.querySelectorAll('[data-edit-subject]').forEach(b=>b.onclick=()=>subjectForm(state.projects.find(p=>p.id===b.dataset.editSubject),render));const form=document.querySelector('#university-filter');if(form)form.onsubmit=e=>{e.preventDefault();query=form.elements.query.value.trim();status=form.elements.status.value;archived=form.elements.archived.checked;render();};document.querySelector('[data-university-reset]')?.addEventListener('click',()=>{query='';status='';archived=false;render();});}
